local modes={"NORMAL","MULTIPLY","SCREEN","OVERLAY","DARKEN","LIGHTEN","COLOR_DODGE","COLOR_BURN","HARD_LIGHT","SOFT_LIGHT","DIFFERENCE","EXCLUSION","HSL_HUE","HSL_SATURATION","HSL_COLOR","HSL_LUMINOSITY","ADDITION","SUBTRACT","DIVIDE"}
local inputs={};for _,b in ipairs({0,1,2,63,127,128,129,192,253,254,255})do for _,s in ipairs({0,1,2,63,127,128,129,192,253,254,255})do table.insert(inputs,{backdrop={b,b,b,255},source={s,s,s,255},opacity=255})end end
local result={inputs=inputs,modes={}};for _,mode in ipairs(modes)do local outputs={};for _,input in ipairs(inputs)do local b=input.backdrop[1];local s=input.source[1];local dst=Image(1,1,ColorMode.RGB);local src=Image(1,1,ColorMode.RGB);dst:drawPixel(0,0,app.pixelColor.rgba(b,b,b,255));src:drawPixel(0,0,app.pixelColor.rgba(s,s,s,255));dst:drawImage(src,Point(0,0),255,BlendMode[mode]);local pixels={string.byte(dst.bytes,1,4)};table.insert(outputs,{rgba=pixels,opaque=pixels})end result.modes[string.lower(mode)]=outputs end
local f=assert(io.open(app.params.output,'w'));f:write(json.encode(result));f:close()
